async function loadDriverDashboard(){const root=document.getElementById('app');if(!root)return;root.innerHTML=`<main class="container driver-shell" id="driver-dashboard"><p class="notice">Loading driver workspace…</p></main>`;const pane=document.getElementById('driver-dashboard');try{const data=await opsApi('driver');pane.innerHTML=`<div class="driver-head"><div><span class="eyebrow">Driver partner</span><h1 class="serif">Today’s rides</h1></div><button class="btn ${data.profile.online?'outline':''}" onclick="toggleDriverAvailability(${!data.profile.online})">${data.profile.online?'Go offline':'Go online'}</button></div><div class="driver-stats"><div><small>Trips today</small><strong>${data.stats.trips||0}</strong></div><div><small>Completed</small><strong>${data.stats.completed||0}</strong></div><div><small>Today’s earnings</small><strong>${opMoney(data.stats.earnings||0)}</strong></div></div>${!data.verified?'<div class="notice error">Your account is not verified. You cannot accept rides until documents are approved.</div>':''}<section class="panel"><h2>Incoming requests</h2>${data.requests?.length?data.requests.map(r=>`<article class="driver-request"><div><strong>${oe(r.category)} · ${r.passengers} passenger(s)</strong><p>${oe(r.pickup)} → ${oe(r.dropoff)}</p><small>${oe(r.trip_type)} · ${r.assistance&&r.assistance!=='None'?oe(r.assistance):'No assistance requested'}${r.fare?' · '+opMoney(r.fare):''}</small></div><div class="driver-actions"><button class="btn small" onclick="driverAction('accept',${r.id})">Accept</button><button class="btn outline small" onclick="driverAction('reject',${r.id})">Reject</button></div></article>`).join(''):'<p class="notice">No assigned requests right now.</p>'}</section></main>`}catch(e){root.innerHTML=`<main class="container section"><div class="empty"><h1>${oe(e.message)}</h1><a class="btn" href="#/cab-partner">Open partner portal</a></div></main>`}}
async function driverAction(action,tripId){try{await opsApi('driver/'+action,{tripId});await loadDriverDashboard()}catch(e){toast(e.message)}}
async function toggleDriverAvailability(online){try{await opsApi('driver/availability',{online});await loadDriverDashboard()}catch(e){toast(e.message)}}
function driverRoute(){return (location.hash.slice(1).split('?')[0]||'/').replace(/^\//,'')==='driver'}
const originalDriverRender=window.render;window.render=function(){if(driverRoute()){setTimeout(loadDriverDashboard,0);return originalDriverRender?.apply(this,arguments)}return originalDriverRender?.apply(this,arguments)};
window.addEventListener('hashchange',()=>{if(driverRoute())loadDriverDashboard()});
setTimeout(()=>{if(driverRoute())loadDriverDashboard()},250);
